// concern-deli: deli and cured-meat cards name the hidden concerns (nitrite, celery powder, phosphates,
// binders, smoke flavoring) and lead with organic / pasture-raised; new sources come from the concern archive.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { nonEmpty } from '../../lib/testGuards.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const card = (id) => { const e = kb.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'kind', 'category']);
const text = (e) => JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k]) => !SKIP.has(k))));

const CURED = ['deli_meat_uncured', 'bacon', 'hot_dogs', 'ham', 'turkey_bacon', 'cured_pork'];
const CARDS = [...CURED, 'pork_cuts_and_enhanced'];
const PICKS = ['pick_sausage', 'pick_jerky'];
const ALL = [...CARDS, ...PICKS];

const root = new URL('../../../docs/sources/concerns/', import.meta.url).pathname;
const archived = new Set();
for (const d of readdirSync(root, { withFileTypes: true }).filter((x) => x.isDirectory())) {
  for (const f of readdirSync(join(root, d.name)).filter((x) => x.endsWith('.md'))) {
    const m = readFileSync(join(root, d.name, f), 'utf8').match(/^url:\s*(\S+)/m);
    if (m) archived.add(m[1]);
  }
}
// The URLs these nine cards carried before concern-deli (2026-10-18); they may stay.
const BEFORE = new Set(["https://extension.oregonstate.edu/catalog/pnw-784-making-cured-bacon-home","https://health.clevelandclinic.org/turkey-bacon-how-healthy-is-it-really","https://www.canr.msu.edu/news/ham_for_the_holidays_and_all_year_long","https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/bacon-and-food-safety","https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/hams-and-food-safety","https://www.law.cornell.edu/cfr/text/9/317.17","https://www.law.cornell.edu/cfr/text/9/317.2","https://www.law.cornell.edu/cfr/text/9/319.140","https://www.law.cornell.edu/cfr/text/9/319.141","https://www.law.cornell.edu/cfr/text/9/319.180","https://www.law.cornell.edu/cfr/text/9/381.173","https://www.ndsu.edu/agriculture/extension/publications/jerky-native-american-inspired-snack-we-all-can-enjoy-today","https://www.nichemeatprocessing.org/uncured-bacon/","https://www.npr.org/sections/thesalt/2019/08/29/755115208/duped-in-the-deli-aisle-no-nitrates-added-labels-are-often-misleading"]);

test('C1 cured cards name celery and nitrite', () => {
  for (const id of nonEmpty(CURED, 'cured', 6)) {
    const t = text(card(id));
    assert.match(t, /celery/i, `${id} celery`);
    assert.match(t, /nitrite/i, `${id} nitrite`);
  }
});

test('C2 decisions lead with organic / pasture / grass-fed', () => {
  for (const id of nonEmpty(CARDS, 'cards', 7)) assert.match(card(id).decision, /organic|pasture|grass-fed/i, `${id} decision`);
});

test('C3 phosphates and binders named', () => {
  for (const id of ['deli_meat_uncured', 'ham', 'hot_dogs']) {
    const t = text(card(id));
    assert.match(t, /phosphate/i, `${id} phosphate`);
    assert.match(t, /binder|carrageenan/i, `${id} binder`);
  }
  assert.match(text(card('pork_cuts_and_enhanced')), /phosphate/i);
});

test('C4 smoke flavoring named', () => {
  for (const id of ['bacon', 'ham', 'hot_dogs']) assert.match(text(card(id)), /smoke flavou?ring|liquid smoke/i, id);
});

test('C5 pick decisions name celery', () => {
  for (const id of nonEmpty(PICKS, 'picks', 2)) assert.match(card(id).decision, /celery/i, id);
});

test('C6 sources come from the concern archive', () => {
  nonEmpty([...archived], 'archived urls', 100);
  for (const id of ALL) {
    const urls = nonEmpty((card(id).sources || []).map((s) => s.url), `${id} sources`, 1);
    assert.ok(urls.some((u) => archived.has(u)), `${id} cites no concern-archive url`);
    for (const u of urls) assert.ok(BEFORE.has(u) || archived.has(u), `${id} url not archived: ${u}`);
  }
});

test('C7 no treatment claims, no first person', () => {
  for (const id of ALL) {
    const t = text(card(id));
    assert.doesNotMatch(t, /\b(causes?|prevents?|lowers? (the )?risk|carcinogen\w*|cancer)\b/i, `${id} treatment`);
    assert.doesNotMatch(t, /\b(I|me|my)\b/, `${id} first person`);
  }
});
// Owns the two-line rewrite's text (docs/CARD-STYLE-SAMPLES.md): every card's decision and
// buying_tips (and egg_labels sources) equal the pin in twoLinePin.js, which older batch tests read through.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { nonEmpty } from '../../lib/testGuards.js';
import { TWO_LINE } from './twoLinePin.js';
import { matchItemToCard } from '../../lib/listMatch.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));

test('every card carries the pinned two-line decision and buying_tips', () => {
  const cards = nonEmpty(kb.entries.filter((e) => e.kind !== 'pick'), 'cards', 180);
  for (const e of cards) {
    assert.ok(TWO_LINE[e.id], `${e.id} has no two-line pin`);
    // Every pinned field, so a field the older tests restore (cart_pick, pick_steps) is still checked live.
    for (const [k, v] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[k], v, `${e.id}.${k}`);
  }
  assert.equal(Object.keys(TWO_LINE).length, cards.length, 'a pin for a card that is gone');
});

// Known gap: lintSections L5 makes the chuck pick carry the G1 term, and that term alone outscores
// beef_cuts_basics for beef_grassfed_vs_grainfed (scorePool's top-2 window), so the pick lands uncarded.
// Pinned null so a matcher or wording change that fixes it (or sends it to the wrong card) goes red.
const KNOWN_UNCARDED = new Set(['beef_cuts_basics']);
test('every pinned cart_pick resolves to its own card on the live KB', () => {
  const ids = nonEmpty(Object.keys(TWO_LINE).filter((id) => TWO_LINE[id].cart_pick), 'pinned cart picks', 3);
  for (const id of ids) {
    const m = matchItemToCard(kb.entries.find((e) => e.id === id).cart_pick);
    assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, KNOWN_UNCARDED.has(id) ? null : id, `${id} cart_pick`);
  }
});

// Two-line card rule check (docs/CARD-STYLE-SAMPLES.md). Usage:
//   node scripts/twoLineCheck.js [proposals.json ...]   (from server/)
// With proposals ({id: {decision, buying_tips}}), checks them applied to an in-memory KB copy;
// without, checks the KB as it stands. Exit 1 on any violation.
import { readFileSync } from 'node:fs';
import { projectEntry } from '../lib/counterCards.js';
import { lintCard, words } from '../lib/counterCardLint.js';

const kb = JSON.parse(readFileSync(new URL('../kristy_perimeter_kb.json', import.meta.url)));
const doLines = JSON.parse(readFileSync(new URL('../lib/doLines.json', import.meta.url)));
const doFor = (id) => (Array.isArray(doLines) ? doLines.find((d) => d.slug === id || d.id === id)?.do : doLines[id]?.do ?? doLines[id]) || '';
const proposals = Object.assign({}, ...process.argv.slice(2).map((f) => JSON.parse(readFileSync(f, 'utf8'))));
const byId = new Map(kb.entries.map((e) => [e.id, e]));
const FIRST_PERSON = /\b(I|me|my|mine|we|our|us)\b/;
const APPROVED_LONG = new Set(['ground_beef_lean_ratio', 'whole_vs_reduced_fat_milk']);
let bad = 0;
const ids = Object.keys(proposals).length ? Object.keys(proposals) : kb.entries.filter((e) => e.kind !== 'pick').map((e) => e.id);
for (const id of ids) {
  const base = byId.get(id);
  if (!base) { console.log(`${id}: NO_SUCH_ENTRY`); bad++; continue; }
  const e = { ...base, ...(proposals[id] || {}) };
  const out = [];
  const tip0 = (e.buying_tips || [])[0] || '';
  // Devon approved the CARD-STYLE-SAMPLES line 1s verbatim (2026-10-17); "10 words plus the food" lets ground beef run 12.
  if (words(e.decision) > (APPROVED_LONG.has(id) ? 12 : 10)) out.push(`LINE1_LONG ${words(e.decision)}w`);
  const card = projectEntry(e, { doLine: doFor(id) });
  if (card.look_for?.[0] !== tip0) out.push(`LINE2_NOT_FIRST_LOOK_FOR (cautionary wording or authored watch_out?)`);
  if (tip0.length > 90) out.push(`LINE2_LONG ${tip0.length}c`);
  for (const [f, v] of [['decision', e.decision], ['tip0', tip0]]) if (FIRST_PERSON.test(v)) out.push(`FIRST_PERSON ${f}`);
  if (/—/.test(e.decision) || /—/.test(tip0)) out.push('EM_DASH');
  for (const v of lintCard(card) || []) out.push(`${v.code}${v.field ? `[${v.field}]` : ''} ${v.detail || ''}`.trim());
  if (out.length) { bad++; console.log(`${id}: ${out.join(' | ')}`); }
}
console.log(`${ids.length} checked, ${bad} with violations`);
process.exit(bad ? 1 : 0);
#!/usr/bin/env node
// Generate server/lib/doLines.json from docs/do-lines-review.md.
//
//   node scripts/buildDoLines.js
//
// WHY THIS FILE EXISTS: THE DEPLOY BOUNDARY. Railway's Root Directory is `server/`, so
// nothing outside it reaches production. Both the counter's card projection and its ask
// pipeline read the reviewed `do` lines from `docs/`, wrapped in a try/catch that fell
// back to an empty Map — so in production every curated card served by /api/counter/ask
// had an EMPTY do line. The do line is the whole point of the card, and asking is the
// lead interaction on the Counter. It had been that way since the lines were authored.
//
// The markdown stays the AUTHORED SOURCE, because it is reviewed by hand and its table
// is the reviewable artifact. This JSON is a build product of it that lives inside the
// deploy boundary, and `doLines.test.js` fails if the two disagree — so the generated
// file cannot drift from the reviewed one.
//
// Run this after editing the review table, and commit the result.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { parseReviewTable } from '../lib/counterCards.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REVIEW = join(__dirname, '..', '..', 'docs', 'do-lines-review.md');
const OUT = join(__dirname, '..', 'lib', 'doLines.json');

const reviewed = parseReviewTable(readFileSync(REVIEW, 'utf8'));
if (!reviewed.size) {
  console.error('[do-lines] the review table parsed to nothing — refusing to write an empty file.');
  process.exit(1);
}

// Slug -> do line. The `flag` column is review metadata and is deliberately not carried:
// production needs the line, not the notes about drafting it.
const out = {};
for (const slug of [...reviewed.keys()].sort()) {
  const line = String(reviewed.get(slug)?.do || '').trim();
  if (line) out[slug] = line;
}

writeFileSync(OUT, `${JSON.stringify(out, null, 2)}\n`, 'utf8');
console.log(`[do-lines] wrote ${Object.keys(out).length} do lines to lib/doLines.json ✓`);
