  bacon: 'Look for pork, salt and named curing agents; read each added ingredient.',
  hot_dogs: 'Named meat first, with no mechanically separated chicken or turkey.',
  ham: 'Next, “Ham With Natural Juices”; “Water Added” means more added solution.',
  turkey_bacon: 'Read the named turkey cut and each curing ingredient after the meat.',
  cured_pork: 'A short curing list names the salt, spices and any added curing agents.',
  pork_cuts_and_enhanced: 'Read beside the cut name for a solution percentage and the added ingredients.',
};
for (const id of ids) {
  entry(id).decision = decisions[id];
  entry(id).sources.push(sources.labels);
}
for (const id of cards) {
