}
for (const id of [...cured, ...picks]) entry(id).sources.push(sources.celery);
for (const id of cured) {
  entry(id).watch_out.unshift('“Uncured” or “no nitrates added” can mean cured with celery powder or juice, a plant source of nitrite. Read the asterisk and ingredients.');
}
for (const id of ['deli_meat_uncured', 'ham', 'hot_dogs']) {
  entry(id).watch_out.push('Skip added phosphates such as sodium phosphate, which hold water in the meat. Binders such as carrageenan and modified food starch thicken or bind it.');
  entry(id).buying_tips.push('Choose meat without carrageenan, modified food starch or maltodextrin binders.');
  entry(id).sources.push(sources.deli, sources.additives, sources.carrageenan, sources.binders);
}
for (const id of ['bacon', 'ham', 'hot_dogs']) {
  entry(id).buying_tips.push('For smoked meat, choose wood-smoked with no added smoke flavoring or liquid smoke. Liquid smoke is condensed smoke added for flavor.');
  entry(id).sources.push(sources.smoke);
}
// Explain the curing source consistently wherever the old definition implied no nitrite.
for (const id of ['turkey_bacon', 'cured_pork']) {
  const e = entry(id);
