entry('turkey_bacon').pick_steps[2] = 'Read the “Uncured” qualifier for celery powder or juice supplying nitrite.';
entry('hot_dogs').buying_tips.push('On beef packs, look for grass-fed and grass-finished with a certifier’s seal.');
entry('deli_meat_uncured').buying_tips[1] = 'Find the asterisk on “no nitrates added”; it can point to celery powder or juice.';
entry('deli_meat_uncured').buying_tips[2] = 'Celery powder or juice supplies nitrite during curing. It is still a curing agent.';
entry('deli_meat_uncured').buying_tips[3] = 'Ask for the counter’s ingredient list; slicing there does not change what went into the meat.';
entry('deli_meat_uncured').why = 'Celery powder or juice supplies nitrite during curing. Whole roasted meat leaves the curing step out.';
entry('deli_meat_uncured').short_answer = '“Uncured” deli meat can still use celery powder or juice as a plant source of nitrite. Read the qualifier and the full ingredient list.';
entry('deli_meat_uncured').detail = '“Uncured” and “no nitrates or nitrites added” can appear on meat cured with celery powder or juice. Celery supplies nitrate that is converted to nitrite during curing. The qualifier names this plant source. Sodium nitrite names a directly added curing agent; celery changes the source, not the curing chemistry. Organic describes the feed standard and pasture-raised describes outdoor access. Neither claim tells you which curing agents or binders were used.';
entry('deli_meat_uncured').kristy_take = 'Whole roasted meat leaves out the cure. At the deli counter, the full ingredient list shows celery curing agents and added binders.';
entry('deli_meat_uncured').labels_decoded[0].meaning = 'May use celery powder or juice to supply nitrite during curing; read the qualifier.';
entry('deli_meat_uncured').tier_note = 'The ingredient list identifies the cure. Organic or pasture-raised meat and fewer additions are sourcing and processing choices.';
entry('deli_meat_uncured').pick_steps[0] = 'Read the “no nitrates added” qualifier for celery powder or juice.';
entry('deli_meat_uncured').science = 'Celery powder or juice supplies nitrate that becomes nitrite during curing. The ingredient list and qualifier name that source on “uncured” meat. Phosphates hold water in the meat, while carrageenan and starch bind or thicken it. Whole roasted meat leaves out the cure; counter slicing alone changes none of the ingredients.';
entry('deli_meat_uncured').watch_out.splice(1, 1);
// Keep the ham naming ladder, without numeric protein thresholds or solution examples.
entry('ham').detail = 'US labeling ties ham names to the protein level in the lean portion. Plain “Ham” comes first, then “Ham With Natural Juices”, then “Ham, Water Added”. “Ham and Water Product” must state the share of its weight that is added ingredients. Fresh ham is the uncured leg of pork and needs cooking; a processed ham labeled “uncured” can still use celery-based curing.';
entry('ham').science = 'Ham is the leg of pork. On cured ham, its product name describes added water: plain “Ham”, then “Ham With Natural Juices”, then “Ham, Water Added”. Phosphates help hold water; binders such as carrageenan thicken it. Celery powder or juice can supply nitrite even on an “uncured” pack. Check whether the label says fully cooked or cook before eating.';
entry('ham').labels_decoded[0].meaning = 'Cured ham with more added water than plain “Ham”, but less than “Ham, Water Added”.';
entry('ham').labels_decoded[1].meaning = 'Cured ham with more added solution than “Ham With Natural Juices”.';
entry('pork_cuts_and_enhanced').question = 'Which pork cut should you buy, and what does “solution added” mean?';
entry('pork_cuts_and_enhanced').short_answer = 'Raw meat with added solution must name it and state its percentage. The solution’s ingredients follow in weight order; look for water, salt and phosphates.';
entry('pork_cuts_and_enhanced').detail = 'Pork can be injected with a solution of water, salt and phosphates to hold moisture. The label must state the solution’s share relative to the raw meat and list its ingredients in descending weight order. Plain pork leaves that added solution out. Organic names the feed standard; a pasture-raised claim alone does not identify the feed.';
entry('pork_cuts_and_enhanced').kristy_take = 'A solution declaration names added water and the other ingredients. Plain pork leaves that solution out.';
entry('pork_cuts_and_enhanced').buying_tips[1] = 'Read for “contains added solution” and its percentage, then check for water, salt and phosphates.';
entry('pork_cuts_and_enhanced').watch_out = [
  '“Enhanced” cannot replace the required solution declaration. Find the percentage beside the product name and read the solution’s ingredients.',
  'Phosphates in the solution help the meat hold water. A pasture-raised or organic claim does not rule out an added solution.',
];
entry('pork_cuts_and_enhanced').science = 'Pork can be injected with water, salt and phosphates to hold moisture. The label must state the solution’s share relative to the raw meat and list what went into it. Organic and pasture-raised describe how the animal was raised; the solution declaration describes what was added afterward.';
entry('pork_cuts_and_enhanced').sources.push(sources.solution, sources.additives);
entry('pork_cuts_and_enhanced').instead = 'An organic or pasture-raised shoulder or roast with pork alone in the ingredient list.';
// Preserve all prior citations exactly; append only objects whose URLs were read from the archive.
let pinText = readFileSync(pinPath, 'utf8');
const pinStart = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const pinEnd = pinText.indexOf('\\n};', pinStart) + 2;
const pins = JSON.parse(pinText.slice(pinStart, pinEnd));
for (const id of ids) {
  const e = entry(id);
  const before = baseline.entries.find(e => e.id === id);
  assert.deepEqual(e.sources.slice(0, before.sources.length), before.sources, "'`${id}: existing sources`);
  pins[id] ||= {};
  for (const [field, value] of Object.entries(e)) {
    if (JSON.stringify(value) !== JSON.stringify(before[field])) pins[id][field] = value;
  }
}
