  const id = cells[1].trim().replaceAll('"'"'`'"', '');
  if ("'!cards.includes(id) || cells[2].trim() !== '"'meat') return line;
  cells[3] = "'` ${decisions[id]} `;
  if (newDo[id]) cells[4] = ` ${newDo[id]} `;
  return cells.join('"'|');
}).join('\\n');
writeFileSync(reviewPath, review);
console.log("'`Updated ${ids.length} entries and their literal pins; preserved every existing citation.`);
