test('NO entry anywhere in the KB claims a health outcome, in either direction', () => {
  // Wider than the label-truth check below: the no-treatment rule is absolute across
  // the whole perimeter, and it is symmetric (nothing cures and nothing causes).
  //
  // ⚠️ `reverse osmosis` IS A WATER TREATMENT, NOT A HEALTH OUTCOME, and it is the one
  // exception this pattern carries. It is carved out by NAME rather than by dropping
  // `reverses?`, which stays live for everything else — the ban is on a food reversing a
  // condition, and "reverse" only stops being that word when "osmosis" follows it.
  // `bottled_water_buying` is why: FDA's standard of identity (21 CFR 165.110) defines
  // purified water as distillation, deionization or reverse osmosis, the phrase is
  // printed on real bottles, and a card that decodes label terms cannot decode that one
  // without saying it. Widened deliberately, like IMPERATIVE_VERBS and the state-word
  // list; the negative lookahead is the whole carve-out, so "reverses inflammation" and
  // "reverse the damage" still fail exactly as before.
  const OUTCOME = /\b(cures?|heals?|prevents?|reverses?(?!\s+osmosis)|detox|remed(y|ies)|immunity|diagnos\w*)\b/i;
  for (const e of perimeterKb.entries) {
    assert.doesNotMatch(JSON.stringify(e), OUTCOME, `${e.id} makes a health-outcome claim`);
  }
});

test('mercury guidance names species and defers anything medical', () => {
  const m = perimeterKb.entries.find((e) => e.id === 'mercury_by_fish');
  assert.ok(m, 'the mercury-by-fish entry must exist');
  const text = JSON.stringify(m).toLowerCase();
  for (const fish of ['sardines', 'skipjack', 'albacore', 'swordfish', 'king mackerel'])
    assert.match(text, new RegExp(fish), `must name ${fish}`);
  assert.match(text, /doctor/, 'anything medical is deferred, never a directive');
  assert.equal(m.evidence_tier, 'established');
});

const BRAND = /whole foods|tyson|perdue|hormel|oscar mayer|applegate|boar.s head|smithfield|jimmy dean|hillshire|butterball|jennie-o|foster farms/i;
const CLAIM = /healthier|healthiest|better for you|lowers|exposure|protein|calorie/i;
const PRICE = /\bcheapest\b|\bprice\b|\$[0-9]/i;
const CURE_WORD = /\b(cured|uncured|nitrite|nitrate|celery powder|celery juice)\b/i;

test('C1 D1 limits hold on every CA-3b card', () => {
  for (const id of BATCH) {
    const e = now(id);
    assert.ok(e, `${id} missing`);
    assert.ok(words(e.decision) <= 14, `${id} decision ${words(e.decision)} words`);
    if (Array.isArray(e.pick_steps)) {
      assert.ok(e.pick_steps.length >= 1 && e.pick_steps.length <= 3, `${id} pick_steps ${e.pick_steps.length}`);
      for (const s of e.pick_steps) assert.ok(words(s) <= 14, `${id} pick_step "${s}"`);
    }
    if (e.kind === 'pick') continue;
    const n = String(e.tier_note || '').trim();
    assert.ok(words(n) >= 5 && words(n) <= 20, `${id} tier_note ${words(n)} words`);
    assert.doesNotMatch(n, /[.!?]\s+\S/, `${id} tier_note is more than one sentence`);
    assert.ok(String(e.instead || '').trim().length > 0 && words(e.instead) <= 24, `${id} instead`);
  }
});

test('C2 no CA-3b decision or cart_pick prints a grass term', () => {
  for (const id of BATCH) {
    const e = now(id);
    assert.doesNotMatch(String(e.decision || ''), /grass-(fed|finished)/i, `${id} decision`);
    assert.doesNotMatch(String(e.cart_pick || ''), /grass-(fed|finished)/i, `${id} cart_pick`);
  }
});

test('C3 chicken_breast survives as a rewrite', () => {
  const e = now('chicken_breast');
  assert.ok(e, 'chicken_breast was removed');
  assert.ok(!RETIRED_IDS.has('chicken_breast'), 'chicken_breast is RETIRED');
  assert.match(String(e.cart_pick || ''), /breast/i);
  assert.notEqual(JSON.stringify(e), JSON.stringify(pre('chicken_breast')), 'chicken_breast unchanged');
});

test('C4 the pass rule holds for every CA-3b id', (t) => {
  for (const id of BATCH) pass.assertPassRule(t, pre(id), now(id));
});

test('C5 brand claim and price greps are zero over changed copy fields', () => {
  let changed = 0;
  for (const id of BATCH) {
    const e = now(id);
    const p = pre(id);
    for (const [f, v] of Object.entries(e)) {
      if (COPY_SKIP.has(f) || JSON.stringify(v) === JSON.stringify(p[f])) continue;
      changed++;
      const s = JSON.stringify(v);
      assert.doesNotMatch(s, BRAND, `${id}.${f} brand`);
      assert.doesNotMatch(s, CLAIM, `${id}.${f} claim-lock word`);
      assert.doesNotMatch(s, PRICE, `${id}.${f} price`);
      assert.doesNotMatch(s, /—/, `${id}.${f} em-dash`);
      assert.doesNotMatch(s, /\b(I|me|my|mine)\b/, `${id}.${f} first person`);
    }
  }
  assert.ok(changed >= 14, `only ${changed} changed copy fields`);
});

test('C6 the full meat section is lint-clean under the meat tip', () => {
  const hits = lint.lintSections([{ ...MEAT_TIP, tip_aligned: true, cards_aligned: true }], kb.entries);
  const bad = hits.filter((h) => h.section === 'meat' && ['SECTION_TIP_REPEATS_CARD', 'SECTION_PHRASE_REPEATED', 'TERM_UNGLOSSED', 'CART_PICK_DISAGREES'].includes(h.code));
  assert.deepEqual(bad, []);
});

test('C7 cure sentences come only from the shared set', () => {
  const allowed = new Set(lint.PRESERVATION_CURE_SENTENCES);
  assert.ok(allowed.size > 0, 'PRESERVATION_CURE_SENTENCES empty');
  for (const id of CURED) {
    const e = now(id);
    const p = pre(id);
    for (const f of ['decision', 'tier_note', 'why', 'short_answer', 'kristy_take']) {
      if (JSON.stringify(e[f]) === JSON.stringify(p[f])) continue;
      for (const s of String(e[f] || '').split(/(?<=[.!?])\s+/)) {
        if (CURE_WORD.test(s) && !/^Cured\b|^Uncured\b/.test(s.trim())) assert.ok(allowed.has(s.trim()), `${id}.${f} authored a cure sentence: ${s}`);
      }
    }
  }
});

test('C8 per-card lints are clean and headlines match', () => {
  for (const id of BATCH) {
    const e = now(id);
    if (e.kind === 'pick' || JSON.stringify(e) === JSON.stringify(pre(id))) continue;
    assert.deepEqual(lint.lintCard(projectEntry(e, { doLine: doLines[id] })), [], `${id} lintCard`);
    assert.deepEqual(flat(lint.readability(e)), [], `${id} readability`);
    assert.deepEqual(flat(lint.lintPickSteps(e)), [], `${id} lintPickSteps`);
  }
});
  assert.ok(!all.includes('see Grass-fed vs. grain-fed beef'), 'stale beef pointer');
  assert.ok(all.includes('How it was raised: see Beef.'), 'no repointed beef pointer');
});

test('C5 meat fronts and why lines pass', () => {
  const notes = kb.entries.map((e) => String(e.tier_note || '').trim()).filter(Boolean);
  for (const id of BATCH) {
    const e = now(id);
    assert.ok(e, `${id} missing`);
    assert.ok(words(e.decision) <= 14, `${id} front is ${words(e.decision)} words`);
    assert.deepEqual(headlineHedge(e.decision), [], `${id} front hedges`);
    const n = String(e.tier_note || '').trim();
    assert.ok(words(n) >= 5, `${id} tier_note too short`);
    assert.doesNotMatch(n, /[.!?]\s+\S/, `${id} tier_note is more than one sentence`);
    assert.doesNotMatch(n, /\b(I|me|my|mine|we|us|our)\b/, `${id} tier_note first person`);
    assert.notEqual(n.toLowerCase().replace(/[^a-z]/g, ''), String(e.evidence_tier).toLowerCase().replace(/[^a-z]/g, ''), `${id} tier_note is the tier name`);
    assert.equal(notes.filter((x) => x === n).length, 1, `${id} tier_note not unique`);
    assert.ok(!PENDING.includes(id), `${id} still pending`);
    assert.deepEqual(lintCard(projectEntry(e, { doLine: doLines[id] })), [], `${id} lint`);
    assert.deepEqual(readability(e), [], `${id} readability`);
    assert.equal(reviewHeadline(id), e.decision, `${id} review headline differs from KB decision`);
  }
  assert.deepEqual([...ESSENTIALS], ['organic_worth_it_by_type', 'egg_labels', 'salmon_wild_vs_farmed', 'label_front_vs_back',
  for (const id of OWN) assert.deepEqual(frontFailures(now(id)), [], id);
});

test('C4 every card front passes corpus-wide', () => {
  const bad = CARDS.map((e) => [e.id, frontFailures(e)]).filter(([, f]) => f.length);
  assert.deepEqual(bad, [], bad.map(([id, f]) => `${id}: ${f.join(', ')}`).join('\n'));
  assert.deepEqual([...ESSENTIALS], ['organic_worth_it_by_type', 'egg_labels', 'salmon_wild_vs_farmed', 'label_front_vs_back',
    'produce_ripeness_by_item', 'beef_grassfed_vs_grainfed', 'judging_meat_at_the_case', 'whole_vs_reduced_fat_milk']);
});

test('C5 claim-lock rule 4 corpus-wide', () => {
  for (const e of CARDS) assert.doesNotMatch(`${e.decision} ${e.tier_note}`, RULE4, e.id);
});

test('C6 sources never shrink and new URLs are archived', () => {
  for (const id of OWN) {
    const have = new Set(urls(now(id)));
    for (const u of urls(pre(id))) assert.ok(have.has(u), `${id} dropped ${u}`);
  }
  for (const e of CARDS) for (const u of urls(e)) if (!PRE_URLS.has(u)) assert.ok(archive.includes(u), `${e.id}: ${u} not in docs/sources/item-cards`);
  assert.ok(!JSON.stringify(kb).includes(UMD), 'umd raw-milk-law URL is in the KB');
rtest('READ_STACKED: a look_for "Term — meaning" separator clears, a second em-dash fires', () => {
  rassert.deepEqual(rcodes({ look_for: ['Term — meaning.'] }), []);
  rassert.deepEqual(rcodes({ look_for: ['Term — meaning — aside.'] }), ['READ_STACKED']);
});

test('sectionRules corpus: lintSections is clean (CA-5 flags turn the section lints on)', () => {
  nonEmpty(sectionRules, 'sectionRules', 6);
  nonEmpty(perimeterKb.entries, 'perimeterKb.entries', 180);
  assert.deepEqual(lintSections(sectionRules, perimeterKb.entries), []);
});

