  if(celery[id]) card.watch_out[0]=celery[id];
  if(additives[id]) card.watch_out[card.watch_out.length-1]=additives[id];
  if(smoke[id]) {
    const index=card.buying_tips.findIndex(t=>t.startsWith('For smoked meat,'));
    card.buying_tips[index]=smoke[id];
