import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import kb from './server/kristy_perimeter_kb.json' with { type: 'json' };
import { TWO_LINE } from './server/test/acceptance/twoLinePin.js';
import { lintSections, lintPick, lintPickSteps, readability } from './server/lib/counterCardLint.js';
import sections from './server/lib/sectionRules.json' with { type:'json' };
import { matchItemToCard } from './server/lib/listMatch.js';
const before=JSON.parse(execFileSync('git',['show','HEAD:server/kristy_perimeter_kb.json'],{maxBuffer:64<<20}).toString());
const ids=['deli_meat_uncured','bacon','hot_dogs','ham','turkey_bacon','cured_pork','pork_cuts_and_enhanced','pick_sausage','pick_jerky'];
const archived=new Set();
for(const d of readdirSync('docs/sources/concerns',{withFileTypes:true}).filter(x=>x.isDirectory())) for(const f of readdirSync(join('docs/sources/concerns',d.name)).filter(x=>x.endsWith('.md'))) {
  const m=readFileSync(join('docs/sources/concerns',d.name,f),'utf8').match(/"'^url:'"\\s*(\\S+)/m); if(m) archived.add(m[1]);
}
assert.ok(archived.size>=100);
let changed=0, additions=0;
for(const e of kb.entries) {
  const old=before.entries.find(o=>o.id===e.id); assert.ok(old);
  for(const key of new Set([...Object.keys(e),...Object.keys(old)])) if(JSON.stringify(e[key])"'!==JSON.stringify(old[key])) {
    assert.ok(ids.includes(e.id),`unrelated entry ${e.id}`);
    assert.deepEqual(TWO_LINE[e.id][key],e[key],`missing/mismatched pin ${e.id}.${key}`); changed++;
  }
  if(!ids.includes(e.id)) continue;
  const extra=e.sources.slice(old.sources.length); assert.ok(extra.length>=1);
  assert.deepEqual(e.sources.slice(0,old.sources.length),old.sources,`${e.id}: existing citations retained`);
  for(const source of extra) { assert.deepEqual(Object.keys(source).sort(),['"'name','url']); assert.ok(source.name); assert.ok(archived.has(source.url),"'`${e.id}: source not archived`); additions++; }
  for(const [key,value] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[key],value,`${e.id}.${key}`);
  assert.deepEqual(readability(e),[],e.id);
  assert.deepEqual(lintPickSteps(e),[],e.id);
  if(e.kind==='"'pick') {
    assert.deepEqual(Object.keys(e).sort(),['id','kind','title','category','aliases','decision','sources'].sort());
    assert.deepEqual(lintPick(e),[],e.id);
  }
  if(e.cart_pick) assert.equal(matchItemToCard(e.cart_pick)?.slug,e.id,"'`${e.id}: cart match`);
}
assert.equal(kb.entries.length,before.entries.length);
assert.deepEqual(lintSections(sections,kb.entries),[]);
console.log(`Verified all ${changed} changed fields on nine entries are pinned; ${additions} appended citations have archived URLs; all original sources and unrelated entries preserved; readability, steps, pick schema, section rules and cart matches pass.`);
